/*
C
C     FFTE: A FAST FOURIER TRANSFORM PACKAGE
C
C     (C) COPYRIGHT SOFTWARE, 2000-2004, ALL RIGHTS RESERVED
C                BY
C         DAISUKE TAKAHASHI
C         GRADUATE SCHOOL OF SYSTEMS AND INFORMATION ENGINEERING
C         UNIVERSITY OF TSUKUBA
C         1-1-1 TENNODAI, TSUKUBA, IBARAKI 305-8573, JAPAN
C         E-MAIL: daisuke@cs.tsukuba.ac.jp
C
C
C     1-D COMPLEX FFT ROUTINE
C
C     FORTRAN77 SOURCE PROGRAM
C
C     CALL ZFFT1D(A,N,IOPT,B)
C
C     A(N) IS COMPLEX INPUT/OUTPUT VECTOR (COMPLEX*16)
C     B(N) IS WORK VECTOR (COMPLEX*16)
C     N IS THE LENGTH OF THE TRANSFORMS (INTEGER*4)
C       -----------------------------------
C         N = (2**IP) * (3**IQ) * (5**IR)
C       -----------------------------------
C     IOPT = 0 FOR INITIALIZING THE COEFFICIENTS (INTEGER*4)
C          = -1 FOR FORWARD TRANSFORM
C          = +1 FOR INVERSE TRANSFORM
C
C     WRITTEN BY DAISUKE TAKAHASHI
C
*/

#include "hpccfft.h"

#ifdef _OPENMP
#include <omp.h>
#endif

int
HPCC_ipow(int x, int p) {
  int i, r;

  if (1 == x || 0 == x) return x;
  if (0 == p) return 1;
  if (-1 == x) return (p & 1) ? -1 : 1;
  if (p < 0) return 0;
  r = 1;
  for (i = 0; i < p; i++) r *= x;
  return r;
}

static int
zfft1d0(fftw_complex *a1, fftw_complex *a2, fftw_complex *b, fftw_complex *c, fftw_complex *d,
  fftw_complex *w1, fftw_complex *w2, fftw_complex *ww1, fftw_complex *ww2, fftw_complex *ww3,
  fftw_complex *ww4, int n1, int n2, int m1, int m2, int *ip1, int *ip2) {

  int lda1, lda2, ldb, ldc, ldww1, ldww2, ldww3, ldww4;
  int ii, ij, ij0, ik, ir, is, jj, i, j;
  int tmin1, tmin2, itmp1;
  fftw_complex ztmp1, ztmp2, ztmp3, ztmp4;

  lda1 = n1;
  lda2 = n2;
  ldb = n1;
  ldc = n2 + FFTE_NP;
  ldww1 = m1;
  ldww2 = m1;
  ldww3 = m2;
  ldww4 = n1/m1;

#ifdef _OPENMP
#pragma omp for private(ij,ij0,ir,jj,i,j,ik,is,ztmp1,ztmp2,ztmp3,ztmp4,tmin1,tmin2,itmp1)
#endif
  for (ii = 0; ii < n1; ii += FFTE_NBLK) {
    for (jj = 0; jj < n2; jj += FFTE_NBLK) {
      tmin1 = ii + FFTE_NBLK;
      V2MIN( tmin1, n1 );

      for (i = ii; i < tmin1; ++i) {
        tmin2 = jj + FFTE_NBLK;
        V2MIN( tmin2, n2 );

        for (j = jj; j < tmin2; ++j) {
          c_assgn( ARR2D(c, j, i-ii, ldc), ARR2D(a1, i, j, lda1) );
        }
      }
    }

    tmin1 = ii + FFTE_NBLK;
    V2MIN( tmin1, n1 );
    for (i = ii; i < tmin1; ++i)
      HPCC_fft235( PTR2D(c, 0, i-ii, ldc), d, w2, n2, ip2 );

    if (HPCC_ipow( 2, ip1[0] ) < FFTE_NBLK || HPCC_ipow( 2, ip2[0] ) < FFTE_NBLK) {
      itmp1 = n2 / m2;
      for (is = 0; is < itmp1; ++is) {
        for (ik = 0; ik < m2; ++ik) {
          j = ik + is * m2;

          tmin1 = ii + FFTE_NBLK;
          V2MIN( tmin1, n1 );
          for (i = ii; i < tmin1; ++i) {
            ir = i / m1;
            ij = i % m1;

            c_assgn(ztmp1, ARR2D(c, j, i-ii, ldc));

            c_assgn(ztmp2, ARR2D(ww1, ij, ik, ldww1));
            c_mul3v(ztmp3, ztmp1, ztmp2);

            c_assgn(ztmp2, ARR2D(ww2, ij, is, ldww2));
            c_mul3v(ztmp1, ztmp3, ztmp2);

            c_assgn(ztmp3, ARR2D(ww3, ik, ir, ldww3));
            c_mul3v(ztmp2, ztmp1, ztmp3);

            c_assgn(ztmp1, ARR2D(ww4, ir, is, ldww4));
            c_mul3v(ztmp3, ztmp2, ztmp1);

            c_assgn(ARR2D(b, i, j, ldb), ztmp3);
          }
        }
      }
    } else {
      ir = ii / m1;
      ij0 = ii % m1;

      itmp1 = n2 / m2;
      for (is = 0; is < itmp1; ++is) {
        for (ik = 0; ik < m2; ++ik) {
          c_assgn(ztmp1, ARR2D(ww3, ik, ir, ldww3));
          c_assgn(ztmp2, ARR2D(ww4, ir, is, ldww4));
          c_mul3v(ztmp4, ztmp1, ztmp2);
          j = ik + is * m2;
          ij = ij0;

          tmin1 = ii + FFTE_NBLK;
          V2MIN( tmin1, n1 );
          for (i = ii; i < tmin1; ++i) {
            c_assgn(ztmp1, ARR2D(ww1, ij, ik, ldww1));
            c_assgn(ztmp2, ARR2D(ww2, ij, is, ldww2));
            c_mul3v(ztmp3, ztmp1, ztmp2);

            c_mul3v(ztmp1, ztmp3, ztmp4);

            c_assgn(ztmp2, ARR2D(c, j, i-ii, ldc));
            c_mul3v(ztmp3, ztmp2, ztmp1);

            c_assgn(ARR2D(b, i, j, ldb), ztmp3);

            ++ij;
          }
        }
      }
    }
  }

#ifdef _OPENMP
#pragma omp for private(i,j,tmin1)
#endif
  for (jj = 0; jj < n2; jj += FFTE_NBLK) {
    tmin1 = jj + FFTE_NBLK;
    V2MIN(tmin1, n2);
    for (j = jj; j < tmin1; ++j) {
      HPCC_fft235( PTR2D(b, 0, j, ldb), c, w1, n1, ip1 );
    }

    for (i = 0; i < n1; ++i)
      for (j = jj; j < tmin1; ++j) {
        c_assgn(ARR2D(a2, j, i, lda2), ARR2D(b, i, j, ldb));
      }
  }

  return 0;
}

static int
settbls(fftw_complex *w1, fftw_complex *w2, fftw_complex *w3, fftw_complex *w4,
  int n1, int n2, int m1, int m2) {

  int j, k, is, ir;
  int ldw1, ldw2, ldw3, ldw4;
  double pi2, px;

  pi2 = 8.0 * atan(1.0);
  px = -pi2 / n1 / n2;

  ldw1 = m1;
  ldw2 = m1;
  ldw3 = m2;
  ldw4 = n1/m1;

#ifdef _OPENMP
#pragma omp parallel
  {
#pragma omp for private(j, ir)
#endif
  for (k = 0; k < m2; ++k) {
    for (j = 0; j < m1; ++j) {
      c_re(ARR2D(w1, j, k, ldw1)) = cos(px * j * k);
      c_im(ARR2D(w1, j, k, ldw1)) = sin(px * j * k);
    }

    for (ir = 0; ir < n1/m1; ++ir) {
      c_re(ARR2D(w3, k, ir, ldw3)) = cos(px * k * ir * m1);
      c_im(ARR2D(w3, k, ir, ldw3)) = sin(px * k * ir * m1);
    }
  }

#ifdef _OPENMP
#pragma omp for private(j, ir)
#endif
  for (is = 0; is < n2/m2; ++is) {
    for (j = 0; j < m1; ++j) {
      c_re(ARR2D(w2, j, is, ldw2)) = cos(px * j * is * m2);
      c_im(ARR2D(w2, j, is, ldw2)) = sin(px * j * is * m2);
    }

    for (ir = 0; ir < n1/m1; ++ir) {
      c_re(ARR2D(w4, ir, is, ldw4)) = cos(px * ir * m1 * is * m2);
      c_im(ARR2D(w4, ir, is, ldw4)) = sin(px * ir * m1 * is * m2);
    }
  }
#ifdef _OPENMP
  }
#endif

  return 0;
}	/* settbls */

int
HPCC_zfft1d(int n, fftw_complex *a, fftw_complex *b, int iopt, hpcc_fftw_plan p) {
  int i;
  int m1, m2, n1, n2, nd;
  double dn;
  int ip[3], ip1[3], ip2[3];
  fftw_complex *w1, *w2, *ww1, *ww2, *ww3, *ww4, *c, *d;

  w1 = p->w1;
  w2 = p->w2;
  ww1 = p->ww1;
  ww2 = p->ww2;
  ww3 = p->ww3;
  ww4 = p->ww4;
  c = p->c;
  d = p->d;

  HPCC_factor235( n, ip );

  if (1 == iopt)
    for (i = 0; i < n; ++i) {
      c_im( a[i] ) = -c_im( a[i] );
    }

  if (n <= FFTE_L2SIZE / 16 / 3 && n <= FFTE_NDA2) {
    if (0 == iopt) {
      HPCC_settbl( w1, n );
      return 0;
    }

    HPCC_fft235( a, b, w1, n, ip );
  } else {
    for (i = 0; i < 3; ++i) {
      ip1[i] = (ip[i] + 1) / 2;
      ip2[i] = ip[i] - ip1[i];
    }

    n1 = HPCC_ipow( 2, ip1[0] ) * HPCC_ipow( 3, ip1[1] ) * HPCC_ipow( 5, ip1[2] );
    n2 = HPCC_ipow( 2, ip2[0] ) * HPCC_ipow( 3, ip2[1] ) * HPCC_ipow( 5, ip2[2] );

    if (HPCC_ipow( 2, ip1[0] ) < FFTE_NBLK || HPCC_ipow( 2, ip2[0] ) < FFTE_NBLK) {
      m1 = HPCC_ipow( 2, ip1[0] / 2 ) * HPCC_ipow( 3, ip1[1] / 2 ) * HPCC_ipow( 5, ip1[2] / 2 );

      m2 = HPCC_ipow( 2, ip2[0] / 2 ) * HPCC_ipow( 3, ip2[1] / 2 ) * HPCC_ipow( 5, ip2[2] / 2 );
    } else {
      m1 = HPCC_ipow( 2, ip1[0] / 2);
      m1 = FFTE_NBLK > m1 ? FFTE_NBLK : m1;

      m2 = HPCC_ipow( 2, ip2[0] / 2);
      m2 = FFTE_NBLK > m2 ? FFTE_NBLK : m2;
    }
    V2MIN( m1, n1 );
    V2MIN( m2, n2 );

    if (0 == iopt) {
      HPCC_settbl( w1, n1 );
      HPCC_settbl( w2, n2 );
      settbls( ww1, ww2, ww3, ww4, n1, n2, m1, m2 );
      return 0;
    }

    nd = (n2 + FFTE_NP) * FFTE_NBLK + FFTE_NP;

#ifdef _OPENMP
#pragma omp parallel private(c,i)
   {
    i = omp_get_thread_num();
    c = p->c + i*p->c_size;
    d = p->d + i*p->d_size;
#endif

    zfft1d0( a, a, b, c, d, w1, w2, ww1, ww2, ww3, ww4, n1, n2, m1, m2, ip1, ip2 );

#ifdef _OPENMP
   }
#endif

  }

  if (1 == iopt) {
    dn = 1.0 / (double)n;
    for (i = 0; i < n; ++i) {
      c_re( a[i] ) *= dn;
      c_im( a[i] ) *= -dn;
    }
  }

  return 0;
}	/* HPCC_zfft1d */

#include <math.h>

#define FFTE_NDA2 65536
#define FFTE_NDA3 4096
#define FFTE_NDA4 256

/* Parameters that affect performance */

/*
  Blocking parameter. Suggested values:
   8 for Pentium III and Athlon
  16 for Pentium4, Athlon XP, Opteron, Itanium and Itanium2
*/
#ifndef FFTE_NBLK
#define FFTE_NBLK 16
#endif

/*
  Padding parameter to avoid cache conflicts.
  Suggested values:
  2 for Pentium III
  4 for Athlon, Athlon XP, Opteron, Itanium
  8 for Pentium4 and Itanium2
*/
#ifndef FFTE_NP
#define FFTE_NP 8
#endif

/* Size of Level 2 cache */
#ifndef FFTE_L2SIZE
#define FFTE_L2SIZE 1048576
#endif

#ifdef LONG_IS_64BITS
typedef unsigned long u64Int_t;
typedef long s64Int_t;
#else
typedef unsigned long long u64Int_t;
typedef long long s64Int_t;
#endif

#include "wrapfftw.h"

extern int HPCC_ipow(int x, int p);

extern int HPCC_zfft1d(int n, fftw_complex *a, fftw_complex *b, int iopt, hpcc_fftw_plan p);
extern int HPCC_fft235(fftw_complex *a, fftw_complex *b, fftw_complex *w, int n, const int *ip);
extern int HPCC_settbl(fftw_complex *w, int n);
extern int HPCC_factor235(int n, int *ip);
extern int HPCC_factor235_8(s64Int_t n, int *ip);

extern int HPCC_bcnrand(u64Int_t n, u64Int_t a, void *x);

#define ARR2D(a, i, j, lda) a[(i)+(j)*(lda)]
#define PTR2D(a, i, j, lda) (a+(i)+(j)*(lda))
#define ARR3D(a, i, j, k, lda1, lda2) a[(i)+(lda1)*((j)+(k)*(lda2))]
#define PTR3D(a, i, j, k, lda1, lda2) (a+(i)+(lda1)*((j)+(k)*(lda2)))
#define ARR4D(a, i, j, k, l, lda1, lda2, lda3) a[(i)+(lda1)*((j)+(lda2)*((k)+(lda3)*(l)))]
#define c_mul3v(v, v1, v2) c_re(v) = c_re(v1) * c_re(v2) - c_im(v1) * c_im(v2); c_im(v) = c_re(v1) * c_im(v2) + c_im(v1) * c_re(v2)
#define c_assgn(d, s) c_re(d)=c_re(s);c_im(d)=c_im(s)
#define V3MIN(r, e, v) r = (e); V2MIN(r, v)
#define V2MIN(r, v) r = (v) < r ? (v) : r
#define EMAX(d, v, e) d=(e); d=d>(v)?d:(v)

#define    Mmax( a_, b_ )      ( ( (a_) > (b_) ) ?  (a_) : (b_) )

#if defined(USING_FFTW)

#include <fftw.h>

#elif defined(USING_FFTW3)

#include <fftw3.h>

typedef int fftw_direction;

#define c_re(c)  ((c)[0])
#define c_im(c)  ((c)[1])

#else

typedef double fftw_real;
typedef struct {
     fftw_real re, im;
} fftw_complex_orig;
typedef fftw_real HPCC_Complex[2];
typedef HPCC_Complex fftw_complex;

typedef enum {
     FFTW_FORWARD = -1, FFTW_BACKWARD = 1
} fftw_direction;
#endif

struct hpcc_fftw_plan_struct {
  fftw_complex *w1, *w2, *ww1, *ww2, *ww3, *ww4, *c, *d;
  int n, c_size, d_size;
  int flags;
  fftw_direction dir;
};
typedef struct hpcc_fftw_plan_struct *hpcc_fftw_plan;

extern hpcc_fftw_plan HPCC_fftw_create_plan(int n, fftw_direction dir, int flags);
extern void HPCC_fftw_destroy_plan(hpcc_fftw_plan plan);
extern void HPCC_fftw_one(hpcc_fftw_plan plan, fftw_complex *in, fftw_complex *out);

#if !defined(USING_FFTW) && !defined(USING_FFTW3)

typedef struct hpcc_fftw_plan_struct *fftw_plan;

#define c_re(c)  ((c)[0])
#define c_im(c)  ((c)[1])

#define fftw_malloc malloc
#define fftw_free free
/* flags for the planner */
#define  FFTW_ESTIMATE (0)
#define  FFTW_MEASURE  (1)

#define FFTW_OUT_OF_PLACE (0)
#define FFTW_IN_PLACE (8)
#define FFTW_USE_WISDOM (16)

#define fftw_create_plan HPCC_fftw_create_plan
#define fftw_destroy_plan HPCC_fftw_destroy_plan
#define fftw_one HPCC_fftw_one

#endif

